	/** 
	 * jumpstart the process by instantiating2 Organization
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		organizationId = OrganizationService.getOrganizationInstance()
		.createOrganization( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		OrganizationService.getOrganizationInstance()
				.createOrganization( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.organizationSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Organization : " + successValue.getOrganizationId());
							  if (successValue.getOrganizationId().equals(organizationId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfOrganizationList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Organization test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on organization consumed")
					);
			subscriber.organizationSubscribe( organizationId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Organization : " + successValue.getOrganizationId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfOrganizationList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on organization for organizationId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Organization. 
	 */
	protected Organization read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Organization" );

		Organization entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Organization with primary key" );
		msg.append( organizationId );
		
		OrganizationFetchOneSummary fetchOneSummary = new OrganizationFetchOneSummary( organizationId );

		try {
			entity = OrganizationService.getOrganizationInstance().getOrganization( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Organization " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Organization.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Organization." );

		StringBuilder msg = new StringBuilder( "Failed to update a Organization : " );        
		Organization entity = read();
		UpdateOrganizationCommand command = generateUpdateCommand();
		command.setOrganizationId(entity.getOrganizationId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Organization." );

			// for use later on...
			organizationId = entity.getOrganizationId();

			OrganizationService proxy = OrganizationService.getOrganizationInstance();  

			proxy.updateOrganization( command ).get();

			LOGGER.info( "-- Successfully saved Organization - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + organizationId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Organization.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Organization." );

		Organization entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Organization with id " + organizationId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Organization with id " + organizationId );

			throw e;
		}

		try{
			OrganizationService.getOrganizationInstance().delete( new DeleteOrganizationCommand( entity.getOrganizationId() ) ).get();
			LOGGER.info( "-- Successfully deleted Organization with id " + organizationId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Organization with id " + organizationId );

			throw e;
		}
	}

	/**
	 * get all Organizations.
	 */
	protected List<Organization> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Organizations:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Organization : " );        
		List<Organization> collection  = new ArrayList<>();

		try {
			// call the static get method on the OrganizationService
			collection = OrganizationService.getOrganizationInstance().getAllOrganization();
			assertNotNull( collection, "An Empty collection of Organization was incorrectly returned.");
			
			// Now print out the values
			Organization entity = null;            
			Iterator<Organization> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getOrganizationId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

